//! Parity gate: assert every Python-oracle case from `parity_fixture.txt`
//! produces the identical bytes in Rust.
//!
//! The fixture is generated by `tests/parity_oracle.py`, which runs the real
//! `json.dumps` call in `ezchain_core.signing` under the project venv. A Rust
//! failure here is a parity failure, not a test bug; do not edit the fixture
//! to go green — fix the implementation and regenerate from the oracle.

use ezchain_jsoncanon::{canonical_json, canonical_object, CanonError, JsonValue, NonFinite};

const FIXTURE: &str = include_str!("parity_fixture.txt");

/// Decode the small ASCII spec grammar the oracle writes. Strings are
/// hex-encoded UTF-8; delimiters (`,`, `]`, `}`) cannot appear in a token.
struct SpecParser<'a> {
    src: &'a str,
    pos: usize,
}

impl<'a> SpecParser<'a> {
    fn new(src: &'a str) -> Self {
        Self { src, pos: 0 }
    }

    fn peek(&self) -> Option<char> {
        self.src[self.pos..].chars().next()
    }

    fn bump(&mut self) -> Option<char> {
        let ch = self.peek()?;
        self.pos += ch.len_utf8();
        Some(ch)
    }

    fn expect(&mut self, expected: char) {
        assert_eq!(
            self.bump(),
            Some(expected),
            "expected {expected:?} at byte {} of {:?}",
            self.pos,
            self.src
        );
    }

    fn token(&mut self) -> &'a str {
        let start = self.pos;
        while let Some(ch) = self.peek() {
            if matches!(ch, ',' | ']' | '}') {
                break;
            }
            self.pos += ch.len_utf8();
        }
        &self.src[start..self.pos]
    }

    fn hex(&mut self) -> &'a str {
        let start = self.pos;
        while self.peek().is_some_and(|ch| ch.is_ascii_hexdigit()) {
            self.pos += 1;
        }
        &self.src[start..self.pos]
    }

    fn value(&mut self) -> JsonValue {
        match self.bump().expect("a value") {
            'z' => JsonValue::Null,
            's' => {
                self.expect(':');
                JsonValue::Str(decode_hex(self.token()))
            }
            'i' => {
                self.expect(':');
                JsonValue::Int(self.token().to_string())
            }
            'd' => {
                self.expect(':');
                JsonValue::Decimal(self.token().to_string())
            }
            'b' => {
                self.expect(':');
                JsonValue::Bool(self.bump() == Some('1'))
            }
            'u' => {
                self.expect(':');
                JsonValue::Unsupported(self.token().to_string())
            }
            'n' => {
                self.expect('f');
                self.expect(':');
                let kind = match self.token() {
                    "nan" => NonFinite::Nan,
                    "inf" => NonFinite::PositiveInfinity,
                    "-inf" => NonFinite::NegativeInfinity,
                    other => panic!("unknown non-finite spelling: {other:?}"),
                };
                JsonValue::NonFinite(kind)
            }
            'a' => {
                self.expect('[');
                let mut items = Vec::new();
                if self.peek() != Some(']') {
                    loop {
                        items.push(self.value());
                        if self.peek() == Some(',') {
                            self.bump();
                        } else {
                            break;
                        }
                    }
                }
                self.expect(']');
                JsonValue::Array(items)
            }
            'o' => {
                self.expect('{');
                let mut fields = Vec::new();
                if self.peek() != Some('}') {
                    loop {
                        let key = decode_hex(self.hex());
                        self.expect(':');
                        let value = self.value();
                        fields.push((key, value));
                        if self.peek() == Some(',') {
                            self.bump();
                        } else {
                            break;
                        }
                    }
                }
                self.expect('}');
                JsonValue::Object(fields)
            }
            other => panic!("unknown spec token: {other:?}"),
        }
    }
}

fn decode_hex(text: &str) -> String {
    let mut bytes = Vec::with_capacity(text.len() / 2);
    let (pairs, rest) = text.as_bytes().as_chunks::<2>();
    assert!(rest.is_empty(), "odd-length hex in fixture: {text:?}");
    for pair in pairs {
        let high = (pair[0] as char).to_digit(16).expect("hex digit") as u8;
        let low = (pair[1] as char).to_digit(16).expect("hex digit") as u8;
        bytes.push(high * 16 + low);
    }
    String::from_utf8(bytes).expect("fixture hex is valid UTF-8")
}

fn hex(bytes: &[u8]) -> String {
    const DIGITS: &[u8; 16] = b"0123456789abcdef";
    let mut out = String::with_capacity(bytes.len() * 2);
    for byte in bytes {
        out.push(DIGITS[(byte >> 4) as usize] as char);
        out.push(DIGITS[(byte & 0x0f) as usize] as char);
    }
    out
}

#[test]
fn python_oracle_parity() {
    let mut passed = 0usize;
    let mut failures: Vec<String> = Vec::new();

    for (index, line) in FIXTURE.lines().enumerate() {
        let fields: Vec<&str> = line.split('\t').collect();
        assert_eq!(fields.len(), 3, "malformed fixture line {}", index + 1);
        let (name, spec, expected) = (fields[0], fields[1], fields[2]);

        let mut parser = SpecParser::new(spec);
        let value = parser.value();
        assert_eq!(
            parser.pos,
            spec.len(),
            "trailing spec bytes on line {} ({name})",
            index + 1
        );

        let actual = match canonical_json(&value) {
            Ok(text) => hex(text.as_bytes()),
            Err(error) => format!("E:{}", error.code()),
        };
        if actual == expected {
            passed += 1;
        } else {
            failures.push(format!(
                "line {} [{name}]: expected {expected}, got {actual}",
                index + 1
            ));
        }
    }

    let total = FIXTURE.lines().count();
    eprintln!("parity: {passed}/{total} cases match the Python oracle");
    if !failures.is_empty() {
        for failure in failures.iter().take(20) {
            eprintln!("  MISMATCH {failure}");
        }
        panic!("{} parity case(s) failed", failures.len());
    }
}

#[test]
fn canonical_object_sorts_top_level_keys() {
    let actual = canonical_object([
        ("b", JsonValue::Int("2".to_string())),
        ("a", JsonValue::Str("x".to_string())),
    ])
    .expect("valid object");
    assert_eq!(actual, "{\"a\":\"x\",\"b\":2}");
}

#[test]
fn refusals_propagate_through_nested_values() {
    let nested = JsonValue::Array(vec![
        JsonValue::Null,
        JsonValue::Unsupported("bytes".to_string()),
    ]);
    assert_eq!(
        canonical_json(&nested),
        Err(CanonError::Unsupported("bytes".to_string()))
    );
}
